function summonBatchStatsV573(items){
 let list=(items||[]).map(x=>typeof x==="number"?{i:x,isNew:false}:x);
 let counts={UR:0,SSR:0,SR:0,R:0},newCount=0;
 list.forEach(x=>{let rank=charRank(x.i);counts[rank]=(counts[rank]||0)+1;if(x.isNew)newCount++;});
 let top=list.reduce((best,x)=>!best||charRankOrder(charRank(x.i))>charRankOrder(charRank(best.i))?x:best,null);
 return {list,counts,newCount,dupCount:Math.max(0,list.length-newCount),top}
}
