function formationGradeV567(arr){
 let a=formationAnalysisV517(arr),syn=literarySynergy(arr),p=unitPower(arr);
 let score=Math.max(0,Math.min(100,Math.round(a.score*.72+Math.min(20,syn.score*.18)+Math.min(8,p/2500))));
 return {score,label:score>=92?"S":score>=82?"A":score>=70?"B":score>=58?"C":"D"}
}
